mapper.select:
SELECT user_id, role, phone, password, name, birth_date, gender, avatar_id, pin, fcm_token, status, created_at, updated_at
FROM users
WHERE user_id = #{id}

SELECT user_id, role, phone, password, name, birth_date, gender, avatar_id, pin, fcm_token, status, created_at, updated_at
FROM users
WHERE phone = #{phone}

mapper.update:
UPDATE users
SET name = #{name},
    avatar_id = #{avatarId}
WHERE user_id = #{id}

UPDATE users

SET fcm_token = #{fcmToken, jdbcType=VARCHAR}
WHERE user_id = #{id}

UPDATE users
SET fcm_token = NULL
WHERE fcm_token = #{fcmToken}
  AND user_id != #{id}

UPDATE users
SET fcm_token = NULL
WHERE user_id = #{id}
  AND fcm_token = #{fcmToken}
